import type { Orientation } from '../lib/deviceTier';
import { asset } from '../lib/asset';

/** Generated by `npm run render:hero` from the same scene the live hero renders. */
export const HERO_ASSET_BASE = asset('hero');

export interface FrameManifest {
  count: number;
  width: number;
  height: number;
  formats: ('avif' | 'webp')[];
  pad: number;
  /** Progress (0–1) of each frame; denser where the scene moves fast. Uniform if absent. */
  stops?: number[];
}

export const manifestUrl = (o: Orientation) => `${HERO_ASSET_BASE}/frames/${o}/manifest.json`;

export const frameUrl = (o: Orientation, index: number, manifest: FrameManifest, format: 'avif' | 'webp') =>
  `${HERO_ASSET_BASE}/frames/${o}/${String(index).padStart(manifest.pad, '0')}.${format}`;

export const posterUrl = (which: 'intro' | 'final', o: Orientation, format: 'avif' | 'webp') =>
  `${HERO_ASSET_BASE}/poster-${which}-${o}.${format}`;

let avifSupport: Promise<boolean> | null = null;

export function supportsAvif(): Promise<boolean> {
  avifSupport ??= new Promise((resolve) => {
    const img = new Image();
    img.onload = () => resolve(img.width > 0);
    img.onerror = () => resolve(false);
    img.src =
      'data:image/avif;base64,';
  });
  return avifSupport;
}
